const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const region = ee.Geometry.Polygon([[
        [78, 68], // East of Taz river delta
        [78, 72],
        [95, 72],
        [95, 68],
        [78, 68]
    ]]);

    const startYear1 = 1973;
    const endYear1 = 1973;
    const startYear2 = 2002;
    const endYear2 = 2002;

    const summerStart = '06-15';
    const summerEnd = '08-15';

    // 2. Data Acquisition & Processing Function
    // This function will get data for a given year, create a composite, and count lakes
    const getLakeCount = function(year, collectionId, ndwiBands) {
        let imageCollection = ee.ImageCollection(collectionId)
            .filterBounds(region)
            .filterDate(year + '-' + summerStart, year + '-' + summerEnd)
            .filter(ee.Filter.lt('CLOUD_COVER', 40)); // Pre-filter to reduce assets

        const collectionSize = imageCollection.size().getInfo();
        if (collectionSize === 0) {
            return {
                size: 0
            };
        }

        // Create a median composite to remove clouds and other artifacts
        const medianImage = imageCollection.median();

        // Calculate NDWI. Bands are provided as an argument.
        const ndwi = medianImage.normalizedDifference(ndwiBands).rename('ndwi');

        // Identify water pixels using a threshold. 0.1 is a common threshold for NDWI.
        const water = ndwi.gt(0.1);

        // Count the number of connected components (lakes)
        // Use a high scale to avoid memory errors on large regions
        const connectedComponents = water.updateMask(water).connectedComponents({
            connectedness: ee.Kernel.plus(1),
            maxSize: 1024
        });

        const countDict = connectedComponents.reduceRegion({
            reducer: ee.Reducer.countDistinct(),
            geometry: region,
            scale: 2000,
            maxPixels: 1e12
        });

        const pixelCount = water.reduceRegion({
            reducer: ee.Reducer.count(),
            geometry: region,
            scale: 2000,
            maxPixels: 1e12
        });

        return {
            size: collectionSize,
            lakeCount: ee.Number(countDict.get('labels')),
            pixelCount: ee.Number(pixelCount.get('ndwi'))
        };
    };

    // 3. Calculation for each year
    // For 1973, use Landsat 1 MSS. Green is B1, NIR is B3. Renaming to standard names.
    const l1 = ee.ImageCollection('LANDSAT/LM01/C02/T1').select(
        ['B4', 'B6'], ['Green', 'NIR']
    );
    const results1973 = getLakeCount(startYear1, l1, ['Green', 'NIR']);

    // For 2002, use Landsat 7 ETM+. Green is B2, NIR is B4.
    const l7 = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2').select(
        ['SR_B2', 'SR_B4'], ['Green', 'NIR']
    );
    const results2002 = getLakeCount(startYear2, l7, ['Green', 'NIR']);

    // 4. Validation & Final Answer
    if (results1973.size === 0 || results2002.size === 0) {
        console.log(`Image count 1973: ${results1973.size}`);
        console.log(`Image count 2002: ${results2002.size}`);
        console.log("Empty collection for one or both years.");
        console.log("C1");
        return;
    }

    const count1973 = results1973.lakeCount.getInfo();
    const pixels1973 = results1973.pixelCount.getInfo();
    const count2002 = results2002.lakeCount.getInfo();
    const pixels2002 = results2002.pixelCount.getInfo();

    console.log(`1973 - Image Collection Size: ${results1973.size}`);
    console.log(`1973 - Approximate Lake Count: ${count1973}`);
    console.log(`1973 - Valid Water Pixels: ${pixels1973}`);
    console.log(`2002 - Image Collection Size: ${results2002.size}`);
    console.log(`2002 - Approximate Lake Count: ${count2002}`);
    console.log(`2002 - Valid Water Pixels: ${pixels2002}`);

    if (pixels1973 === 0 || pixels2002 === 0) {
        console.log("No valid water pixels found after processing for one or both years.");
        console.log("C2");
        return;
    }

    if (count1973 === null || count2002 === null || count1973 === undefined || count2002 === undefined) {
        console.log("Calculation failed, result is null.");
        console.log("C3");
        return;
    }

    console.log(`Comparison: Did lake count decrease from ${count1973} (1973) to ${count2002} (2002)?`);

    if (count2002 < count1973) {
        console.log("A");
    } else {
        console.log("B");
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE().catch(e => {
    console.error(`Error: ${e}`);
    console.log("D");
});
